174				slog.Int64("reaction_id", int64(reaction.ID)),
175				slog.Int64("creator_id", int64(reaction.CreatorID)),
176				slog.String("content_id", reaction.ContentID),
177			)
178			return nil, status.Errorf(codes.NotFound, "reaction creator not found")
179		}
180		return reactionMessage, nil
181	}
